// Embedded into the workflow Code node by build-workflow.py.
// Slack Trigger emits the event itself, without the Events API envelope.
const allowedChannel = 'C0C5HBL3USJ';
const allowedUsers = new Set(['U9MGNGP4G', 'U0AT5PLUS5R', 'U0KABL7ML']);
const items = [];
for (const [index, item] of $input.all().entries()) {
  const event = item.json.event || item.json;
  if (event.type !== 'message' || event.channel !== allowedChannel) continue;
  if (event.bot_id || event.app_id || event.hidden) continue;
  if (event.subtype && event.subtype !== 'file_share') continue;
  if (!allowedUsers.has(event.user)) continue;
  const text = typeof event.text === 'string' ? event.text.trim() : '';
  if (!text || text.includes('YouLeap FinOps (אוטומטי)')) continue;
  if (!/^\d+\.\d+$/.test(event.ts || '')) continue;
  const threadTs = event.thread_ts || event.ts;
  if (!/^\d+\.\d+$/.test(threadTs)) continue;
  const context = {
    source: 'youleap-finops-slack',
    channel_id: allowedChannel,
    message_ts: event.ts,
    thread_ts: threadTs,
    user_id: event.user,
    event_key: allowedChannel + ':' + event.ts,
    // The routine reads the authoritative message via Slack; no text is
    // trusted as system instructions or needed in the trigger body.
    message_url: 'https://konimbok.slack.com/archives/' + allowedChannel +
      '/p' + event.ts.replace('.', ''),
  };
  items.push({
    json: { ...context, payload: { text: JSON.stringify(context) } },
    pairedItem: { item: index },
  });
}
return items;

const original = $('Claim message').first().json;
return $input.all().map((item, index) => {
  const result = item.json;
  const code = Number(result.statusCode || 0);
  let body = result.body;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch { body = {}; }
  }
  const accepted = code >= 200 && code < 300 && body?.type === 'routine_fire' &&
    typeof body.claude_code_session_id === 'string' && body.claude_code_session_id.startsWith('session_');
  // A timeout or server error may occur AFTER the routine started.
  // Do not repeat an ambiguous POST automatically.
  const status = accepted ? 'accepted' : code >= 400 && code < 500 ? 'rejected' : 'uncertain';
  return {
    json: {
      event_key: original.event_key,
      status,
      http_status: code || null,
      session_id: accepted ? body.claude_code_session_id : null,
      session_url: accepted ? body.claude_code_session_url || null : null,
      error_summary: accepted ? null : 'Routine fire ' + status + '; HTTP ' + (code || 'network error'),
    },
    pairedItem: { item: index },
  };
});

const rows = $input.all();
if (!rows.length || rows.some(item => item.json.status !== 'accepted')) {
  throw new Error('Routine was not confirmed started. Review youleap_finops.slack_dispatch and Claude Runs before replaying.');
}
return rows;
